#define TAU (2.0 * 3.14159)
#define ONE cos(TAU)
#define TWO (ONE + ONE)
#define HALF (ONE / TWO)
#define ZERO sin(TAU)
#define SMALL (ONE / pow(TAU, ONE + HALF))
#define TINY (ONE / (TAU * TAU))

const float softness = ONE / (TAU * TAU * TAU);

float sdCircle(vec2 p, float r) {
    return length(p) - r;
}

float sdRing(vec2 p, float r, float t) {
    return abs(sdCircle(p, r)) - t;
}

float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,ZERO)) + min(max(d.x,d.y),ZERO);
}

void mixSdf(
    float sdf,
    vec3 c,
    inout vec3 last
) {
    float a = smoothstep(-softness, softness, sdf);
    last = mix(c, last, a);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv -= HALF;
    uv.x *= iResolution.x / iResolution.y;
    uv *= TWO;

    float diag = abs((uv.x + uv.y) * HALF) - TINY;
    float colorMix = step(sin(diag * diag * TAU), ZERO);

    vec3 primaryBlue = vec3(HALF * HALF, HALF * HALF, ONE);
    vec3 primaryWhite = vec3(ONE);
    vec3 secondaryOrange = vec3(ONE, HALF, SMALL);
    vec3 secondaryBlack = vec3(ZERO);

    vec3 primary = mix(primaryBlue, primaryWhite, colorMix);
    vec3 secondary = mix(secondaryOrange, secondaryBlack, colorMix);

    vec3 col = primary;
    // larger circle
    mixSdf(sdRing(uv, ONE - TINY, TINY), secondary, col);
    // slightly smaller inner circle
    float pointSevenFive = mix(HALF, ONE, HALF);
    float innerCircleRadius = ONE - SMALL - SMALL;
    mixSdf(sdCircle(uv, innerCircleRadius), secondary, col);

    float upperRadius = TWO / TAU;
    // upper circle outside
    mixSdf(
        sdCircle(
            uv - vec2(ZERO, innerCircleRadius - upperRadius + SMALL),
            upperRadius
        ),
        primary,
        col
    );
    // inner line
    mixSdf(
        sdBox(uv, vec2(SMALL * HALF, innerCircleRadius + SMALL)),
        primary,
        col
    );
    // upper circle inside
    mixSdf(
        sdCircle(
            uv - vec2(ZERO, innerCircleRadius - upperRadius + SMALL),
            upperRadius - SMALL
        ),
        secondary,
        col
    );

    // Output to screen
    fragColor = vec4(col,ONE);
}
